  if (customer.yearsWithMHPCO >= LOYALTY_YEARS) total -= base * LOYALTY_DISCOUNT;
  total += base * FIRST_INSURANCE_SURCHARGE;
  if (isFollowUpContract) total -= base * FOLLOW_UP_DISCOUNT;
  return Math.ceil(total + PROCESSING_FEE);
}

